#pragma once
#include <array>
#include <cmath>
#include "FeatureExtractor.h"
#include "ModelWeights.h"   // generated by tools/train_model.py

// Logistic regression inference: risk = sigmoid(w . x + b).
// Weights are trained offline in Python and compiled in as constants,
// so there is no heap allocation and no network call on the hot path.
class RiskEngine {
public:
    double evaluate(const Features& f) const {
        const std::array<double, 3> x{f.gap_cv, f.payload_cv, f.top_endpoint_share};
        double z = model::BIAS;
        for (std::size_t i = 0; i < x.size(); ++i) z += model::WEIGHTS[i] * x[i];
        return sigmoid(z);   // 0.0 = human-like, 1.0 = bot-like
    }

    double evaluate(double gap_cv, double payload_cv, double top_share) const {
        return evaluate(Features{gap_cv, payload_cv, top_share});
    }

private:
    static double sigmoid(double z) { return 1.0 / (1.0 + std::exp(-z)); }
};
